    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "requests\n| where timestamp > ago(7d)\n| extend uid = tostring(column_ifexists('user_Id', ''))\n| summarize UniqueUsers = dcountif(uid, isnotempty(uid)), TotalRequests = count()\n| project UniqueUsers, TotalRequests",
        "size": 4,
        "title": "Unique Visitors (7d)",
        "queryType": 0,
        "resourceType": "microsoft.insights/components",
        "visualization": "tiles",
        "tileSettings": {
          "showBorder": false,
          "titleContent": {
            "columnMatch": "UniqueUsers",
            "formatter": 1,
            "formatOptions": {
              "showIcon": true
            }
          },
          "leftContent": {
            "columnMatch": "UniqueUsers",
            "formatter": 12,
            "formatOptions": {
              "palette": "blue"
            }
          }
        }
      },
      "name": "UniqueVisitors"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "requests\n| where timestamp > ago(7d)\n| summarize TotalPageViews = countif(url has '/posts/' or url has '/published/' or (url !has '/api/' and isnotempty(url)))\n| project TotalPageViews",
        "size": 4,
        "title": "Total Page Views (7d)",
        "queryType": 0,
        "resourceType": "microsoft.insights/components",
        "visualization": "tiles",
        "tileSettings": {
          "showBorder": false,
          "titleContent": {
            "columnMatch": "TotalPageViews",
            "formatter": 1
          },
          "leftContent": {
            "columnMatch": "TotalPageViews",
            "formatter": 12,
            "formatOptions": {
              "palette": "green"
            }
          }
        }
      },
      "name": "TotalPageViews"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "requests\n| where timestamp > ago(7d)\n| extend sid = tostring(column_ifexists('session_Id', '')), uid = tostring(column_ifexists('user_Id', ''))\n| summarize SessionsBySessionId = dcountif(sid, isnotempty(sid)), SessionsByUserId = dcountif(uid, isnotempty(uid))\n| project Sessions = iff(SessionsBySessionId > 0, SessionsBySessionId, SessionsByUserId)",
        "size": 4,
        "title": "Sessions (7d)",
        "queryType": 0,
        "resourceType": "microsoft.insights/components",
        "visualization": "tiles",
        "tileSettings": {
          "showBorder": false,
          "titleContent": {
            "columnMatch": "Sessions",
            "formatter": 1
          },
          "leftContent": {
            "columnMatch": "Sessions",
            "formatter": 12,
            "formatOptions": {
              "palette": "purple"
            }
          }
        }
      },
      "name": "SessionCount"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "requests\n| where timestamp > ago(7d)\n| summarize AvgDurationMs = avg(duration)\n| project AvgDuration = round(coalesce(AvgDurationMs, 0.0), 2)",
        "size": 4,
        "title": "Avg Request Duration (ms)",
        "queryType": 0,
        "resourceType": "microsoft.insights/components",
        "visualization": "tiles",
        "tileSettings": {
          "showBorder": false,
          "titleContent": {
            "columnMatch": "AvgDuration",
            "formatter": 1
          },
          "leftContent": {
            "columnMatch": "AvgDuration",
            "formatter": 12,
            "formatOptions": {
              "palette": "orange"
            }
          }
        }
      },
      "name": "AvgSessionDuration"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "let data = requests\n| where timestamp > ago(7d)\n| where isnotempty(url) and url !has '/api/'\n| extend Page = coalesce(tostring(parse_url(url).Path), name)\n| summarize Views = count() by Page;\ndata\n| union (datatable(Page:string, Views:long) [ 'No data yet', 0 ])\n| summarize Views = sum(Views) by Page\n| order by Views desc",
        "size": 0,
        "title": "Top Pages",
        "queryType": 0,
        "resourceType": "microsoft.insights/components",
        "visualization": "table",
        "gridSettings": {
          "rowLimit": 10,
          "filter": true,
          "sortBy": [
            {
              "itemKey": "Views",
              "sortOrder": 2
            }
          ]
        },
        "chartSettings": {
          "seriesLabelSettings": [
            {
              "seriesName": "Views",
              "color": "blue"
            }
          ]
        }
      },
      "name": "TopPages"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "let data = requests\n| where timestamp > ago(7d)\n| extend browser = tostring(column_ifexists('client_Browser', ''))\n| summarize Views = count() by Browser = iff(isempty(browser), 'Unknown', browser);\ndata\n| union (datatable(Browser:string, Views:long) [ 'No data yet', 0 ])\n| summarize Views = sum(Views) by Browser\n| order by Views desc",
        "size": 0,
        "title": "Traffic by Browser",
        "queryType": 0,
        "resourceType": "microsoft.insights/components",
        "visualization": "piechart",
        "chartSettings": {
          "seriesLabelSettings": [
            {
              "seriesName": "Views",
              "color": "green"
            }
          ]
        }
      },
      "name": "BrowserTraffic"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "let data = requests\n| where timestamp > ago(7d)\n| extend region = tostring(column_ifexists('client_CountryOrRegion', ''))\n| summarize Views = count() by Region = iff(isempty(region), 'Unknown', region);\ndata\n| union (datatable(Region:string, Views:long) [ 'No data yet', 0 ])\n| summarize Views = sum(Views) by Region\n| order by Views desc",
        "size": 0,
        "title": "Traffic by Region",
        "queryType": 0,
        "resourceType": "microsoft.insights/components",
        "visualization": "table",
        "gridSettings": {
          "rowLimit": 15,
          "filter": true,
          "sortBy": [
            {
              "itemKey": "Views",
              "sortOrder": 2
            }
          ]
        }
      },
      "name": "RegionTraffic"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "let start = startofday(ago(7d));\nlet bins = range Day from start to startofday(now()) step 1d;\nlet data = requests\n| where timestamp > ago(7d)\n| summarize Views = count() by Day = bin(timestamp, 1d);\nbins\n| join kind=leftouter data on Day\n| project timestamp = Day, Views = coalesce(Views, 0)\n| order by timestamp asc",
        "size": 0,
        "title": "Daily Page Views Trend",
        "queryType": 0,
        "resourceType": "microsoft.insights/components",
        "visualization": "linechart",
        "chartSettings": {
          "seriesLabelSettings": [
            {
              "seriesName": "Views",
              "color": "purple"
            }
          ]
        }
      },
      "name": "DailyTrend"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "let start = startofday(ago(7d));\nlet bins = range Day from start to startofday(now()) step 1d;\nlet data = requests\n| where timestamp > ago(7d)\n| extend uid = tostring(column_ifexists('user_Id', ''))\n| summarize Users = dcountif(uid, isnotempty(uid)) by Day = bin(timestamp, 1d);\nbins\n| join kind=leftouter data on Day\n| project timestamp = Day, Users = coalesce(Users, 0)\n| order by timestamp asc",
        "size": 0,
        "title": "Daily Unique Users Trend",
        "queryType": 0,
        "resourceType": "microsoft.insights/components",
        "visualization": "columnchart",
        "chartSettings": {
          "seriesLabelSettings": [
            {
              "seriesName": "Users",
              "color": "blue"
            }
          ]
        }
      },
      "name": "DailyUsersTrend"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "let data = requests\n| where timestamp > ago(7d)\n| where isnotempty(name)\n| summarize AvgDurationMs = avg(duration), Failures = countif(success == false), Total = count() by name\n| extend FailureRate = iff(Total == 0, 0.0, (todouble(Failures) / todouble(Total)) * 100.0)\n| project Endpoint = name, ['Avg Duration (ms)'] = round(coalesce(AvgDurationMs, 0.0), 2), ['Failure Rate (%)'] = round(FailureRate, 2);\ndata\n| union (datatable(Endpoint:string, ['Avg Duration (ms)']:real, ['Failure Rate (%)']:real) [ 'No data yet', 0.0, 0.0 ])\n| order by ['Avg Duration (ms)'] desc",
        "size": 0,
        "title": "API Performance",
        "queryType": 0,
        "resourceType": "microsoft.insights/components",
        "visualization": "table",
        "gridSettings": {
          "rowLimit": 10,
          "filter": true
        }
      },
      "name": "APIPerformance"
    }
  ],
  "isLocked": false,
